[AttributeUsage(AttributeTargets.Parameter)]
class A : Attribute
{
    public int Prop { get; set; }
}
class Program
{
    static void Main()
    {
        const int N = 10;
        const int Unused = 20;
        var lam = ([A(Prop = N)] int x) => { };
        lam(100);
    }
}

